{"PLEAD","reg=civilian,worker|tmp=fresh",{"Take the rifle, I got no shells for it, I been carrying it for show","I stocked shelves, that's my whole life, start to finish - please"},false,false,false,{[1]="firearm"}},
{"PLEAD","role=family_man",{"Please don't shoot. You can still change your mind"},false,false,false,{[1]="firearm"}},
{"PLEAD","reg=civilian,family,worker,rescue|tmp=fresh",{"Please don't shoot me! I'll do anything, just don't shoot!","Don't shoot! Please! I want to live!","I got nothing, see?! Hands are empty- please don't!","No gun, I have no gun! Just stop shooting at me!","I'm begging you, put the gun down - I'll leave","Please don't stab me! Please! Take whatever you want!","Put the knife away! I'm not going to hurt you!","Not the blade! I'll give you anything!","Not that bat again! Please, I'll go!","Put the bat down! I'll leave, please...","Please! I can't take another hit from that pipe!","Don't punch me again! Please!","Stop punching me! I'll do whatever you ask!","Don't run me over! Please! I'm just trying to get through!","Please stop swinging at me! I surrender!","Don't swing it at me! I'll go, I'll go!","Please, please don't hurt me. I've had enough","I'll give you anything, just take it and go","I'm nobody, I'm nobody important - please","I didn't do anything to you! Why are you doing this?","That's all I have, that's all I own - please leave me the boots","You can have the food, just leave the photos, they're all I've got of her","I've been robbed already today, there's nothing left to take"},false,false,false,{[1]="firearm",[2]="firearm",[4]="firearm",[5]="firearm",[6]="blade",[7]="blade",[8]="blade",[9]="blunt",[10]="blunt",[11]="blunt",[12]="fists",[13]="fists",[14]="vehicle",[15]="melee",[16]="melee"}},
