{"RETREAT","",{"We need to get away from this!","Back off! It isn't worth dying here!","Don't stay just to be brave!","Come on, let's get out of this!","This is going bad. Move back!","I'd rather leave than die!","Enough! Let's go!","Pull away before it gets worse!","We don't have to win this one!","Leave it! Keep yourself alive!","Get away while you still can!","I'm not staying for more of this!","Back, back! Give yourself room!","This isn't getting better. Let's leave!"}},
{"RETREAT","reg=civilian,family,worker,rescue",{"{He}'s got a gun! I'm leaving, I'm leaving, don't shoot!","I'm getting out of here, nobody told me about guns","That knife is too much for me - I'm done","Keep that bat away! I'm leaving!","I'm done! I'm leaving, you can keep your fists to yourself","Get away from this! Don't wait around!","I'm leaving, I'm leaving - don't swing that at me!","I'm leaving! I'm leaving, all right?","Come on, back off! Everyone back off!"},false,false,false,{[1]="firearm",[2]="firearm",[3]="blade",[4]="blunt",[5]="fists",[7]="melee"}},
{"RETREAT","reg=law",{"Fall back! Don't stay for more of this!","Pull back! Shooter's got us pinned!"},false,false,false,{[2]="firearm"}},
{"RETREAT","reg=law,swat,military,elite",{"Falling back! Taking fire!"},false,false,false,{[1]="firearm"}},
{"RETREAT","reg=elite",{"Get away! I can't take much more!","Disengaging"}},
{"RETREAT","reg=outlaw,raider,gang,club,crime,prison",{"{He}'s too good with that gun! Back off, back off!","Screw this! We're out of here, {he}'s shooting!","Get back from that blade! Get back!","That bat hurts too much - back off, we're done here","Those fists hurt, back off! We'll get {him} later!","{He} swings too hard! Pull back!","Fall back! Go, go!","This isn't worth it! Leave!"},false,false,false,{[1]="firearm",[2]="firearm",[3]="blade",[4]="blunt",[5]="fists",[6]="melee"}},
